BEGIN;

-- 1) 既存46問（q35を除く全47問中）に point/why_asked/kid/eg/terms/vs を非破壊マージ
UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"python-drill-q01": {"point": ".append(x)は引数をそのままリストの末尾に追加し、引数なしの.pop()は末尾の要素を取り出して削除する。", "why_asked": ".pop()やremove()などの破壊的メソッドは戻り値の有無・中身を勘違いしやすく、意図せず元データを壊してしまうバグの温床になるから。", "kid": "appendで末尾に''d''を足し、popで末尾を取り出して削除するので、itemsは追加前とほぼ同じ状態に戻り、popの戻り値であるremovedに取り出された値が入る。", "eg": "レジに並んだお客さんの列の最後に1人並ばせて、すぐその最後の人を呼び出して列から抜くようなもの。列の長さは結局変わらない。", "terms": [[".append(x)", "リストの末尾にxを1つの要素として追加する破壊的メソッド。戻り値はNone。"], [".pop()", "引数を省略するとリストの末尾の要素を削除して、その値を返す破壊的メソッド。"]], "vs": ".append()は戻り値がNoneなので、変数に代入しても中身は入らない。一方.pop()は削除した値を返すので、removed = items.pop()のように受け取れる。この「戻り値があるかないか」の違いを混同しやすい。"}, "python-drill-q02": {"point": ".insert(i, x)は指定インデックスiの位置にxを挿入し、.remove(x)は値xと一致する最初の要素を探して削除する。", "why_asked": "insertの第一引数を「値」と勘違いしたり、removeを「インデックス指定」と混同すると、意図と違う場所を操作してしまうから。", "kid": "insert(1, 15)でインデックス1の位置に15を挟み込み、remove(30)で値30を探して取り除くので、[10, 15, 20]という結果になる。", "eg": "本棚のインデックス1番目の位置に新しい本を差し込み（insert）、タイトルで探した本を1冊抜き取る（remove）ようなもの。", "terms": [[".insert(i, x)", "インデックスiの位置にxを挿入する破壊的メソッド。既存の要素は後ろにずれる。"], [".remove(x)", "値がxと一致する最初の要素を探して削除する破壊的メソッド。見つからないとValueError。"]], "vs": ".insert(i, x)の第一引数はインデックス（位置）、.remove(x)の引数は値そのもの。同じ「要素を操作する」メソッドでも引数の意味がまったく違う点が混同しやすい。"}, "python-drill-q03": {"point": "スライスs[start:stop]は終端stopを含まず、負のインデックスは末尾から数え、s[::step]はstepおきに要素を拾う。", "why_asked": "終端が含まれない・負のインデックスの数え方・stepの意味を勘違いすると、思っていた範囲より1つ多い/少ないデータを取得してしまうから。", "kid": "s[1:4]はインデックス1から3まで、s[-2:]は末尾から2つ、s[::2]は先頭から1つおきに拾うので、それぞれ[1, 2, 3]、[4, 5]、[0, 2, 4]になる。", "eg": "本棚の何番目から何番目まで、あるいは後ろから何冊、1冊おきに、といった取り出し方を指定するようなもの。「何番目まで」は含まない点に注意。", "terms": [["s[start:stop]", "startからstopの手前までの要素を取り出すスライス。stopのインデックスは含まない。"], ["s[start:stop:step]", "stepおきに要素を取り出すスライス。省略時のstepは1。"]], "vs": "s[1:4]は「4個目まで」ではなく「インデックス4の手前まで」。s[-2:]の-2は「後ろから2番目から末尾まで」という範囲指定であり、「後ろから2個」という個数指定ではない点も混同しやすい。"}, "python-drill-q04": {"point": "dict.get(key, default)はキーが無ければdefaultを返すだけでエラーにならないが、dict[key]の角括弧アクセスはキーが無いとKeyErrorを送出する。", "why_asked": "存在しないかもしれないキーに角括弧でアクセスしてプログラムを落としてしまうミスは実務でも頻発するため、安全に取得する.get()との使い分けを知っておく必要があるから。", "kid": "user.get(\"age\", 0)は\"age\"キーが無いのでデフォルト値0を返すが、その直後のuser[\"age\"]は角括弧アクセスなのでキーが無いことがそのままエラーになる。", "eg": "受付で「名簿に無ければ『不明』と答えてください」と頼む(.get)のと、名簿に無い名前をそのまま呼び上げて答えが返ってこず立ち往生する([])くらいの違い。", "terms": [[".get(key, default)", "キーが存在すればその値、無ければdefaultを返す辞書のメソッド。エラーにならない。"], ["dict[key]", "角括弧によるアクセス。キーが存在しないとKeyErrorを送出する。"]], "vs": ".get()は第二引数を省略するとキーが無い場合にNoneを返す（エラーにはならない）。一方[]は省略のしようがなく、無ければ必ず例外という違いがある。"}, "python-drill-q05": {"point": "dict.items()は(キー, 値)のタプルを要素とするビューを返すので、for文でk, vのように分解代入（アンパック）できる。", "why_asked": "items()が何を返しているかを知らないと、for k, v in dict:のように書いて余計なエラーを踏んだり、キーと値の取得を回りくどく書いてしまうから。", "kid": "prices.items()は(\"tea\", 300)や(\"coffee\", 400)のようなペアを順に返すので、for文のk, vにそれぞれキーと値が入る。", "eg": "商品名と値段が書かれた値札を1枚ずつめくって、名前欄と値段欄を同時に読み上げていくようなもの。", "terms": [[".items()", "辞書の(キー, 値)ペアを順に返すビューオブジェクト。"], ["タプルのアンパック", "(a, b)のような複数値をk, vのように別々の変数へ一度に分解代入すること。"]], "vs": "for k in prices:と書くとキーしか取り出せない。値まで同時に取り出すにはfor k, v in prices.items():のようにitems()を使う必要がある点が混同しやすい。"}, "python-drill-q06": {"point": "split(区切り文字)は区切り文字を明示すると、連続する区切りの間に空文字''''の要素を作る。", "why_asked": "CSVのようなデータをsplitで分割するとき、空欄（連続するカンマ）が空文字として残ることを知らないと、要素数がずれて後続の処理がバグるから。", "kid": "\"apple,banana,,cherry\"をカンマで区切ると、bananaとcherryの間に何もない部分が空文字として残るので[''apple'', ''banana'', '''', ''cherry'']になり、それを-で結合すると空文字の場所が--として現れる。", "eg": "駅名が「新宿, 渋谷, , 品川」のようにカンマ区切りで書かれていて、途中に空欄の駅名があると、そこは「何もない駅名」として1つ分カウントされてしまうようなもの。", "terms": [[".split(sep)", "区切り文字sepで文字列を分割してリストにするメソッド。区切り文字を明示すると連続する区切りの間に空文字が残る。"], ["\"-\".join(list)", "リストの各要素を\"-\"で連結して1つの文字列にするメソッド。"]], "vs": "引数なしの.split()は空白文字を区切りとして連続する空白をまとめて無視するが、.split(\",\")のように区切り文字を明示すると、連続する区切りの間の空文字は無視されずそのまま要素になる、という違いがある。"}, "python-drill-q07": {"point": ".strip()は文字列の両端の空白だけを取り除く（間の空白は残る）。f-stringの{}内はPythonの式として評価され、メソッド呼び出しもそのまま使える。", "why_asked": "ユーザー入力やファイルから読み込んだ文字列には前後に余計な空白が混ざりやすく、.strip()を知らないと比較や表示がずれるバグを踏むから。", "kid": "name.strip()で\"  Yu  \"の前後の空白だけが取り除かれ\"Yu\"になり、f-stringの{}の中でその結果がそのまま文中に埋め込まれる。", "eg": "紙の両端の余白だけを切り落として、真ん中の文字はそのまま残すようなもの。", "terms": [[".strip()", "文字列の先頭と末尾の空白（改行やタブも含む）だけを取り除くメソッド。中間の空白は残る。"], ["f-string", "f\"...\"の{}内にPythonの式を書くと、評価結果がそのまま文字列に埋め込まれる書き方。"]], "vs": ".strip()は両端だけを削る。文字列中の空白もまとめて詰めたい場合は\" \".join(s.split())のような別の書き方が必要になる点を混同しやすい。"}, "python-drill-q08": {"point": "range(start, stop, step)はstartから始まり、stepずつ増減しながらstopの手前で止まる。", "why_asked": "range()の第3引数stepの意味やstopが「含まれない」ことを勘違いすると、ループの回数や境界がずれるオフバイワンエラーを起こしやすいから。", "kid": "range(2, 10, 3)は2から始まり3ずつ増えるので2, 5, 8と続き、次の11はstop=10を超えるためそこで止まる。", "eg": "2キロ地点から3キロおきに看板を立てていき、10キロ地点を超えたら立てるのをやめる、というようなもの。", "terms": [["range(start, stop, step)", "startからstopの手前まで、stepずつ増える（または減る）数列を生成する組み込み関数。"], ["range(stop)", "引数を1つだけ渡した場合は0から始まり、stopの手前まで1ずつ増える数列になる。"]], "vs": "range(10)やrange(2, 10)のようにstepを省略すると1ずつの増加になる。第3引数を指定して初めて増分を変えられる、という点で省略形と混同しやすい。"}, "python-drill-q09": {"point": "リストへのinは要素の完全一致を調べ、文字列へのinは部分文字列として含まれているかを調べる。", "why_asked": "同じin演算子でも対象の型によって「完全一致」か「部分一致」かが変わることを知らないと、文字列検索のつもりが意図しない一致をしてしまうから。", "kid": "\"banana\" in fruitsはリストの要素として完全に一致するのでTrue、\"banana\" in \"I like bananas\"は文字列の中に\"banana\"という並びが含まれているのでこちらもTrueになる。", "eg": "リストへのinは「名簿に同じ名前の人がまるごといるか」を確認するようなもの、文字列へのinは「長い文章の中にその単語が一部として紛れ込んでいないか」を確認するようなもの。", "terms": [["in（リストに対して）", "リストの要素の中に指定した値と完全一致するものがあるかを調べる演算子。"], ["in（文字列に対して）", "文字列の中に指定した部分文字列が含まれているかを調べる演算子。"]], "vs": "\"banana\" in \"bananas\"はTrueになるが、\"banana\" == \"bananas\"はFalse。inは「含まれるか」、==は「完全に同じか」という違いを混同しやすい。"}, "python-drill-q10": {"point": "dict.update(other)は同じキーの値を上書きし新しいキーを追加する。dict.pop(key)はそのキーを削除しつつ値を返す。", "why_asked": "update()が既存の値を上書きすることや、pop()が削除と同時に値を取り出せることを知らないと、設定のマージ処理などで意図しない値が残ったり消えたりするから。", "kid": "update()でretriesが5に上書きされtimeoutが追加され、その後pop(\"debug\")でdebugキーが削除されつつその値Falseが取り出される。", "eg": "設定用紙に新しい項目を上書き修正・追記して(update)、その後1つの項目をシートから切り取って手元に控える(pop)ようなもの。", "terms": [[".update(other)", "他の辞書otherの内容で、同じキーは上書きし無いキーは追加する破壊的メソッド。"], [".pop(key)", "指定したキーを辞書から削除し、その値を返すメソッド。"]], "vs": "del config[\"debug\"]でも削除できるが戻り値は無い。.pop(key)は削除と同時に値を受け取れる点が違う。"}, "python-drill-q11": {"point": ".append(x)はxをそのまま1つの要素として追加し、.extend(x)はxの中身を展開して1つずつ追加する。", "why_asked": "リストにリストを足したいときにappendとextendを取り違えると、意図せずネストしたリスト（リストの中にリストが入った状態）を作ってしまうから。", "kid": "a.append([3, 4])は[3, 4]をひとかたまりのまま追加するのでリストの中にリストが入り、b.extend([3, 4])は中身の3と4を1つずつ追加するのでフラットなリストになる。", "eg": "荷物を1箱まるごと棚に置く(append)のと、箱を開けて中身の商品を1つずつ棚に並べる(extend)ような違い。", "terms": [[".append(x)", "xを1つの要素としてそのままリスト末尾に追加する。"], [".extend(iterable)", "iterableの中身を1つずつ展開してリスト末尾に追加する。"]], "vs": "a += [3, 4]はextend()と同じ「展開して追加」の挙動になる。a = a + [3, 4]も見た目は似ているが新しいリストを作る点でappend/extendとは異なる。"}, "python-drill-q12": {"point": "sorted(x)は新しいソート済みリストを返すだけで元のリストは変えない。x.sort()は元のリスト自体を並び替え、戻り値はNone。", "why_asked": "sort()の戻り値をresult = nums.sort()のように受け取るとNoneが入ってしまう有名なバグがあり、sorted()との使い分けを知らないと踏みやすいから。", "kid": "sorted(nums)はその時点の昇順コピーをresultに渡すだけで、後からnums.sort(reverse=True)しても影響を受けない。numsの方は自分自身が降順に書き換わる。", "eg": "コピー用紙を1枚取って並び替えたものを別の人に渡す(sorted)のと、原本そのものを並び替えてしまう(sort)ような違い。", "terms": [["sorted(x)", "元のxを変えずに新しいソート済みリストを返す組み込み関数。"], ["x.sort()", "リストx自身を並び替える破壊的メソッド。戻り値はNone。"]], "vs": "result = nums.sort()のように書くとresultにはNoneが入ってしまう有名な罠がある。並び替えた結果を変数で受け取りたいならsorted()を使う。"}, "python-drill-q13": {"point": ".find()は見つからない場合-1を返すが、.index()は見つからない場合ValueErrorを送出する。", "why_asked": "見つからない可能性がある検索でindex()を使うと例外でプログラムが落ちるため、findとindexのどちらを使うべきか使い分けを知っておく必要があるから。", "kid": "s.find(\"z\")は\"z\"が見つからないので-1を返して処理が続くが、s.index(\"z\")は見つからないとその場でValueErrorを送出し、そこで処理が止まる。", "eg": "探し物が見つからなかったときに「無かったよ」とだけ静かに報告してくれる係(find)と、「無い！」と大声でクレームを上げて足を止めてしまう係(index)のような違い。", "terms": [[".find(sub)", "部分文字列subの位置を返す。見つからなければ-1を返す（例外にならない）。"], [".index(sub)", "部分文字列subの位置を返す。見つからなければValueErrorを送出する。"]], "vs": "リストにも同様に.index()があり見つからないとValueErrorになるが、リストには.find()に相当するメソッドは無い点も紛らわしい。"}, "python-drill-q14": {"point": "&は積集合（共通要素）、|は和集合（すべての要素）、-は差集合（左にあって右に無い要素）を返す。", "why_asked": "重複データの抽出や差分検出でset演算を使う場面が実務でも多く、記号の意味を取り違えると欲しい結果と逆のものを取得してしまうから。", "kid": "a & bは両方に共通する2と3、a | bは両方を合わせた1〜4すべて、a - bはaにあってbには無い1だけが残る。", "eg": "aのグループとbのグループの集合写真を撮るとして、両方に写っている人(&)、どちらかに写っていれば全員(|)、aだけに写っている人(-)を選び出すようなもの。", "terms": [["&（積集合）", "両方のセットに共通する要素だけを取り出す演算子。"], ["|（和集合）", "両方のセットの要素をすべて合わせた演算子。"], ["-（差集合）", "左のセットにあって右のセットに無い要素を取り出す演算子。"]], "vs": "a - bとb - aは結果が違う（非対称）。a - bは「aにあってbに無い」1、b - aは「bにあってaに無い」4になる点を混同しやすい。"}, "python-drill-q15": {"point": "タプルや複数の値をまとめて代入するとき、左辺に変数を並べておくと右辺の要素数と一致する限りそれぞれの変数に分解代入（アンパック）される。", "why_asked": "座標や関数の複数戻り値をx, y = ...のように受け取る場面は頻出で、変数の数と値の数が合わないとValueErrorになることも含めて理解しておく必要があるから。", "kid": "x, y = pointでタプルの1つ目が変数x、2つ目が変数yに分解され、a, b, c = 1, 2, 3も同様に3つの変数へ分解された上でa + b + c = 6が計算される。", "eg": "3人分の給料袋をまとめて渡されたときに、封を開けて1人ずつの手元に配り分けるようなもの。", "terms": [["アンパック（分解代入）", "タプルやリストなどの複数の値を、対応する数の変数へ一度に分解して代入すること。"], ["タプル", "()で表される、作成後は中身を変更できない（イミュータブルな）順序付きのデータ列。"]], "vs": "変数の数と値の数が一致しないとValueErrorになる（例: x, y = 1, 2, 3は値が多すぎてエラー）。今回は数が一致しているので正常に動く。"}, "python-drill-q16": {"point": "[式 for 変数 in 反復 if 条件]の形のリスト内包表記は、条件に合う要素だけを式で変換してリストにする。", "why_asked": "forループとifで何行も書く処理を1行で表現できる分、条件がどこにかかっているか（要素の絞り込みか、それとも変換か）を読み違えるとバグに気づきにくいから。", "kid": "if n % 2 == 0で偶数の2, 4, 6だけに絞り込んでから、それぞれをn * nで2乗するので[4, 16, 36]になる。", "eg": "教室の中から偶数番の出席番号の子だけを選んで(if)、その子たちの身長を記録し直す(n * n)ようなもの。", "terms": [["リスト内包表記", "[式 for 変数 in 反復可能オブジェクト if 条件]の形で新しいリストを作る書き方。"], ["if条件（内包表記内）", "forで取り出した要素のうち、条件を満たすものだけを残すフィルタ。"]], "vs": "[n * n for n in nums]（if無し）は全要素を2乗するが、if n % 2 == 0を付けると偶数だけに絞り込んでから2乗する点が違う。"}, "python-drill-q17": {"point": "{key式: value式 for 変数 in 反復}の形の辞書内包表記は、各要素からキーと値のペアを作って辞書にする。", "why_asked": "リストから辞書への変換を手書きのforループで書くと冗長になりがちで、内包表記で簡潔に書けることと、key: valueの順序を知っておく必要があるから。", "kid": "words内の各単語wについて、wをキー、len(w)（文字数）を値にしたペアを作るので{''a'': 1, ''bb'': 2, ''ccc'': 3}になる。", "eg": "名前のリストから、名前をラベルに、その名前の文字数を中身にしたカードを1枚ずつ作るようなもの。", "terms": [["辞書内包表記", "{key式: value式 for 変数 in 反復可能オブジェクト}の形で新しい辞書を作る書き方。"], ["len(x)", "文字列やリストなどの長さ（要素数）を返す組み込み関数。"]], "vs": "[len(w) for w in words]（リスト内包表記）は長さだけのリスト[1, 2, 3]になるが、{w: len(w) for w in words}（辞書内包表記）は単語と長さのペアの辞書になる点が違う。"}, "python-drill-q18": {"point": "sorted(x, key=関数)は「関数の戻り値」を比較基準にして並び替える。lambda p: p[1]はタプルの2番目の要素（年齢）を取り出す関数。", "why_asked": "リストの中の複数の値を持つ要素（タプルや辞書）を特定のフィールドで並び替えたい場面は実務で頻出で、keyの意味を理解していないと名前順など意図しない基準で並んでしまうから。", "kid": "key=lambda p: p[1]で各人のタプルから年齢（2番目の値）だけを取り出して比較基準にするので、年齢の低いKei(29)、Yu(34)、Rio(41)の順に並ぶ。", "eg": "名前と年齢が書かれたカードの束を、名前ではなく年齢の数字だけを見て若い順に並べ替えるようなもの。", "terms": [["key引数", "sorted()やsort()に渡す、各要素から比較用の値を取り出す関数。"], ["lambda 引数: 式", "名前を付けずにその場で定義する小さな関数（無名関数）。"]], "vs": "sorted(people)（key無し）はタプルの1番目の要素（名前）から順に比較するので名前のアルファベット順になる。key=lambda p: p[1]を指定して初めて年齢基準になる点が違う。"}, "python-drill-q19": {"point": "map(f, iterable)は各要素にfを適用した結果を、filter(f, iterable)はfがTrueを返す要素だけを返す。どちらもイテレータを返すのでlist()で包んで中身を見る。", "why_asked": "map/filterはイテレータ（一度きりの生成器）を返すので、list()で包まずにそのままprintするとmapオブジェクトの表示になってしまい、値が見えないまま戸惑うから。", "kid": "map(lambda x: x * x, nums)は各要素を2乗した[1, 4, 9, 16, 25]を作り、filter(lambda x: x % 2 == 0, nums)は偶数だけを残した[2, 4]を作る。", "eg": "全員の身長を2倍に記録する係(map)と、背の順で条件に合う人だけを選び出す係(filter)のような違い。", "terms": [["map(f, iterable)", "iterableの各要素にfを適用した結果を順に返すイテレータを作る関数。"], ["filter(f, iterable)", "iterableの要素のうちfがTrueを返すものだけを残すイテレータを作る関数。"]], "vs": "map/filterが返すのはイテレータそのものであり、リストではない。list(map(...))のようにlist()で包んで初めて中身の並びが見える形になる点を混同しやすい。"}, "python-drill-q20": {"point": "zip(a, b)は複数のイテラブルを同じ位置どうしのペアにまとめ、enumerate(x)はそれに0始まりの連番を付ける。", "why_asked": "複数のリストを対応付けながら番号も振りたい場面（採点結果の一覧表示など）でzipとenumerateの組み合わせは頻出で、順序と番号の始まりを取り違えるとずれた出力になるから。", "kid": "zip(names, scores)がnamesとscoresを順番にペアにし、enumerate()がそのペアの並びに0から始まる番号を付けるので、最初の行はインデックス0とペア(\"a\", 90)を分解した\"0 a 90\"になる。", "eg": "出席番号のリストと点数のリストを横に並べて、1組ずつ左から番号を振っていくようなもの。", "terms": [["zip(a, b)", "複数のイテラブルを同じ位置どうしでペアにして順に返す関数。"], ["enumerate(x, start=0)", "xの各要素に0から始まる連番を付けて(番号, 要素)のペアを返す関数。"]], "vs": "enumerate(names, scores)のように直接複数のリストを渡すことはできない。番号を付けたい対象はzip()で先に1つのイテラブルにまとめてからenumerate()に渡す必要がある。"}, "python-drill-q21": {"point": "*argsは位置引数をまとめてタプルとして受け取り、**kwargsはキーワード引数をまとめて辞書として受け取る。", "why_asked": "可変長引数を受け取る関数（デコレータやラッパー関数など）を書く・読む場面で頻出のため、argsとkwargsがそれぞれどんな型で受け取られるかを正確に知っておく必要があるから。", "kid": "summarize(1, 2, name=\"Yu\", age=34)を呼ぶと、位置引数の1と2がargsというタプル(1, 2)にまとまり、キーワード引数のname=\"Yu\"とage=34がkwargsという辞書{''name'': ''Yu'', ''age'': 34}にまとまる。", "eg": "受付で、名前の書かれていない荷物はまとめて棚に並べ(*args)、宛名が書かれた荷物は宛名ごとに仕分けて置く(**kwargs)ように分けて受け取るようなもの。", "terms": [["*args", "関数定義で余った位置引数をタプルとしてまとめて受け取る書き方。"], ["**kwargs", "関数定義で余ったキーワード引数を辞書としてまとめて受け取る書き方。"]], "vs": "*argsで集まるのはタプル、**kwargsで集まるのは辞書。同じ「余った引数をまとめる」仕組みでも集まる型が違う点を混同しやすい。"}, "python-drill-q22": {"point": "関数のデフォルト引数は関数定義時に1回だけ評価され、以降の呼び出しで使い回される。ミュータブルなリストや辞書をデフォルトにすると、前回の呼び出しの変更が残ったまま次の呼び出しに引き継がれる。", "why_asked": "「毎回呼び出すたびに空リストから始まる」という思い込みで書いてしまう有名な罠で、実務でも気づかないまま蓄積バグの原因になりやすいから。", "kid": "def add_item(item, bucket=[])のbucket=[]は関数定義時に1度だけ作られる同じリストなので、1回目の呼び出しでbucketに''x''が追加され、2回目の呼び出しでもそのbucketがそのまま使われて''y''が追加される。", "eg": "毎回新品だと思って使っているメモ帳が、実は最初の1冊をずっと使い回していて、前回書いたメモが消えずに残っているようなもの。", "terms": [["デフォルト引数", "関数呼び出し時に引数が省略された場合に使われる値。関数定義時に1回だけ評価される。"], ["ミュータブル", "リストや辞書のように、作成後も中身を変更できるデータ型。"]], "vs": "デフォルト引数をNoneにしておき、関数の中でif bucket is None: bucket = []のように毎回新しいリストを作るのが定石の回避策。bucket=[]と直接書く場合との違いを意識する必要がある。"}, "python-drill-q23": {"point": "==は値（中身）が等しいかを比較し、isは同一オブジェクト（メモリ上の同じ実体）かどうかを比較する。", "why_asked": "「値が同じなら同じオブジェクトのはず」という思い込みでisを使うと、値は同じでも別々に作られたオブジェクトではFalseになる罠を踏むから。", "kid": "aとbは中身が同じ別々のリストなのでa == bはTrueだがa is bはFalse、cはc = aによってaと全く同じオブジェクトを指しているのでa is cはTrueになる。", "eg": "同じデザインの財布を2人がそれぞれ別に持っている(a==bだがa is bはFalse)のと、1つの財布を2人が「自分の財布」と呼んで共有している(a is c)ような違い。", "terms": [["==", "オブジェクトの値（中身）が等しいかどうかを比較する演算子。"], ["is", "2つの変数が同一のオブジェクト（メモリ上の同じ実体）を指しているかを比較する演算子。"]], "vs": "c = aは新しいリストを作らず、aと同じオブジェクトをcという名前でも指すようにするだけの代入。これに対しb = [1, 2, 3]のように改めてリストを書くと、値は同じでも別オブジェクトが作られる点が違う。"}, "python-drill-q24": {"point": ".copy()は「浅い」コピーで、外側のリストだけを複製し、内側にネストしたリストなどは元と同じオブジェクトを参照し続ける。", "why_asked": "「copy()すれば完全に独立したデータになる」という思い込みは実務でもハマりやすい罠で、ネストしたデータ構造を安全に複製するにはcopy.deepcopy()が必要だと知らないと、意図せず元データを壊してしまうから。", "kid": "shallow = original.copy()で外側のリストは新しく作られるが、中の[1, 2]や[3, 4]自体は元と同じオブジェクトのままなので、shallow[0].append(99)で内側のリストを変更するとoriginal側にもその変更が反映される。", "eg": "引き出しの棚板だけを新品に交換して、棚の中身の箱はそのまま元の箱を使い回すようなもの。箱の中身をいじれば、元の棚から見ても中身は変わって見える。", "terms": [[".copy()（浅いコピー）", "外側の入れ物だけを複製し、内側の要素（リストなど）は元のオブジェクトを共有し続けるコピー方法。"], ["copy.deepcopy()", "内側の要素まですべて再帰的に複製し、完全に独立したコピーを作る関数。"]], "vs": "copy.deepcopy(original)を使えば内側のリストまで別オブジェクトとして複製されるため、shallow[0].append(99)をしてもoriginalには影響しない。.copy()との一番の違いは「内側まで複製するかどうか」。"}, "python-drill-q25": {"point": "丸括弧()で書くとジェネレータ式になり要素は必要になるまで計算しない遅延評価、角括弧[]のリスト内包表記は全要素をすぐに計算してメモリに保持する。", "why_asked": "大量データを扱うときにリスト内包表記を使うとメモリを一気に消費してしまうことがあるため、いつ遅延評価（ジェネレータ）に切り替えるべきかを知っておく必要がある。", "kid": "genはまだ中身を計算しておらず必要になった時に1個ずつ計算する。lstは最初から100万個ぶん全部を計算してメモリに置いてしまう。", "eg": "genは注文が入ってから1皿ずつ作るお店、lstは来客前に100万皿を全部作り置きしておくお店のようなもの。", "terms": [["ジェネレータ式 (…)", "丸括弧で書く内包表記。要素を必要になるまで計算しない遅延評価をする"], ["リスト内包表記 […]", "角括弧で書く内包表記。全要素をすぐに計算してリストに格納する"], ["range()", "指定範囲の整数を順に生成するイテラブル。それ自体はリストではない"]], "vs": "ジェネレータ式とリスト内包表記は括弧の種類しか見た目の違いがないが、メモリ使用量と評価タイミングが根本的に異なる。またジェネレータは1度しか走査できない使い切りである点にも注意。"}, "python-drill-q26": {"point": ":=（walrus演算子）は式の中で変数へ代入しながら、その代入した値をその場の評価にも使える構文。", "why_asked": "内包表記やif条件の中で「一度計算した値を条件判定にも結果生成にも使い回したい」場面でコードが簡潔になるため、意味を知らないと書き方も読み方も分からなくなる。", "kid": "y := x * 2でyにx*2を代入しつつ、その値が6より大きいかを同時に判定している。6より大きいのはx=4,5,6のときで、そのときのy(8,10,12)がresultに入る。", "eg": "レシートの合計金額を計算すると同時に、その金額が予算オーバーかどうかもその場でチェックするようなもの。", "terms": [[":= (walrus演算子)", "式の中で変数へ代入しつつ、その代入した値を式の結果としても使える演算子（Python 3.8以降）"], ["内包表記のif節", "生成する要素を絞り込む条件。条件がTrueになった要素だけが結果に残る"]], "vs": "通常の=は文であり式の中には書けないが、:=は式なので条件式の中にも書ける。y = x*2と書いて別行でif y > 6とするのと最終結果は同じだが、1行で完結できる点が違う。"}, "python-drill-q27": {"point": "*変数は「残り全部」をリストとしてまとめて受け取るアンパック構文。", "why_asked": "先頭・末尾だけ取り出して残りをまとめたい場面（データの最初と最後だけ特別扱いしたいときなど）で頻出するため、挙動を知らないと結果の型や要素数を誤解しやすい。", "kid": "firstが先頭の95、lastが末尾の40を受け取り、間に挟まれた60,70,85はまとめてmiddleというリストに入る。", "eg": "電車の先頭車両と最後尾車両だけ名前を付けて、真ん中の車両は「その他の車両たち」として1つのグループにまとめるようなもの。", "terms": [["*変数（アンパック時）", "代入の左辺で使うと、余った要素をまとめてリストとして受け取る"], ["アンパック代入", "リストやタプルの要素を複数の変数に一度に分配して代入すること"]], "vs": "*middleが受け取るのは常にリストであり、要素が1個でも0個でもリストのまま（例えばscoresが3要素ならmiddleは空リスト[]になる）。タプルにはならない点が誤解しやすい。"}, "python-drill-q28": {"point": "all()は全要素が条件を満たすときだけTrue、any()はいずれか1つでも満たせばTrue。", "why_asked": "「全部〜か」と「1つでも〜か」を取り違えると条件分岐のロジックが逆になり、バグの温床になるため正確に区別しておく必要がある。", "kid": "numsの中に奇数の7が混ざっているのでall(...)はFalse。10より大きい要素は1つもないのでany(...)もFalse。", "eg": "all()はクラス全員が宿題を出したかどうかの確認、any()は1人でも欠席者がいるかどうかの確認のようなもの。", "terms": [["all(iterable)", "イテラブルの全要素がTrueと評価されるときだけTrueを返す"], ["any(iterable)", "イテラブルの要素のうち1つでもTrueと評価されればTrueを返す"], ["ジェネレータ式", "()内にfor/ifを書く遅延評価の式。all()やany()に直接渡せる"]], "vs": "all([])はTrue、any([])はFalseになる（空のイテラブルを渡したときの挙動が逆になる）という点も紛らわしいので覚えておくとよい。"}, "python-drill-q29": {"point": "「A if 条件 else B」は条件式（三項演算子）で、条件がTrueならA、FalseならBを式の値として返す。", "why_asked": "通常のif/else文と混同しやすく、境界値（60を含むか含まないか）の読み違いがバグに直結するため。", "kid": "score >= 60を満たせば\"pass\"、満たさなければ\"fail\"になる。60はちょうど60以上なので\"pass\"側に入る。", "eg": "60点以上なら合格ハンコ、それ未満なら不合格ハンコをその場で1つだけ押していくようなもの。", "terms": [["条件式（三項演算子）", "value_if_true if 条件 else value_if_false という形で、1行で条件分岐の値を作る式"], ["リスト内包表記との組み合わせ", "内包表記の式部分に条件式を書くと、要素ごとに違う値を生成できる"]], "vs": "内包表記の中の「if」は2種類の意味を持つので混同注意: 式の直後に書くif~elseは条件式（三項演算子で値を選ぶ）、for節の後ろに書くifは要素を絞り込むフィルタで、書く位置がまったく違う。"}, "python-drill-q30": {"point": "文字列に対する*は「繰り返し連結」、+は「連結」を意味する。", "why_asked": "数値の掛け算・足し算と記号が同じなので、対象の型によって演算の意味が変わることを知らないと出力を誤読する。", "kid": "\"-\" * 5は\"-\"を5回繰り返して\"-----\"になり、\"py\" + \"thon\"はそのままつながって\"python\"になる。", "eg": "*は同じスタンプを5回連続で押す動作、+は2枚の紙をのりで貼り合わせる動作のようなもの。", "terms": [["文字列 * 整数", "文字列をその整数回だけ繰り返して連結した新しい文字列を作る"], ["文字列 + 文字列", "2つの文字列をそのままつなげた新しい文字列を作る"]], "vs": "数値同士の*・+は「掛け算・足し算」だが、文字列に対する*・+は「繰り返し・連結」というまったく別の意味になる。数値と文字列を混ぜて演算しようとするとエラーになる点も注意。"}, "python-drill-q31": {"point": "grid[i][j]は「外側のリストのi番目」の「さらに内側のj番目」を取り出し、len()は外側のリストの要素数だけを数える。", "why_asked": "二次元配列的な入れ子構造の添字アクセスと、len()が数えている対象（外側だけで内側の中身までは数えない）を取り違えると、意図した要素と違うものを読んでしまうため。", "kid": "grid[1]は2番目の内側リスト[3, 4]で、そこからさらに[0]で先頭の3を取る。len(grid)は内側のリストがいくつあるか（3つ）を数える。", "eg": "本棚（grid）の2段目（grid[1]）から1冊目の本（[0]）を取るようなもので、len(grid)は「本棚の段数」を数えているのであって本の総冊数ではない。", "terms": [["grid[i][j]", "外側リストのi番目要素（内側リスト）から、さらにj番目の要素を取り出すネストした添字アクセス"], ["len()", "リストなどのイテラブルの要素数（直下の要素の数）を返す組み込み関数"]], "vs": "len(grid)は内側のリストの中身まで数えない（合計6個の数値があっても3としか出ない）。全要素数を数えたい場合はsum(len(row) for row in grid)のように書く必要がある点が誤解されやすい。"}, "python-drill-q32": {"point": "0・空文字\"\"・空リスト[]・Noneはfalsy（Falseとして扱われる）、それ以外の非ゼロ・非空の値はtruthy。", "why_asked": "if文で明示的な比較をせずに「if x:」とだけ書くコードが多いため、何がFalse扱いされるかを知らないと条件分岐の意図を読み違える。", "kid": "0、空文字\"\"、空リスト[]、Noneの4つだけFalseになり、1、\"a\"、[1]は中身があるのでTrueになる。", "eg": "空っぽの箱・ゼロ枚のカード・何も書かれていない紙は「無い」扱い、中身が1つでも入っている箱は「ある」扱いにする判定のようなもの。", "terms": [["bool()", "値をTrue/Falseに変換する組み込み関数"], ["falsy", "bool()でFalseと評価される値（0, \"\", [], {}, None など）"], ["truthy", "bool()でTrueと評価される値（falsy以外すべて）"]], "vs": "0とNoneは見た目が違うがどちらもfalsyという点、逆に\"0\"（文字列のゼロ）は空文字ではないのでtruthyになる点が特に混同しやすい。"}, "python-drill-q33": {"point": "continueは今回のループの残り処理をスキップして次の周回へ進み、breakはループ自体をその場で終了する。", "why_asked": "continueとbreakの効果範囲（1回スキップか、ループ全体の終了か）を混同すると、意図しない回数だけループが回ってしまうため。", "kid": "偶数のiはcontinueでprintされず、iが5になった瞬間はprintより先にbreakでループを抜けるので、結局1と3だけが表示される。", "eg": "バスの車内アナウンスで「偶数の駅はスキップ」（continue）、「5番目の駅で運行終了、到着放送はしない」（break）をするようなもの。", "terms": [["continue", "ループの残りの処理を飛ばして、次の周回の先頭に戻る"], ["break", "ループ自体をその時点で終了して抜ける"], ["% 演算子", "割り算の余りを求める。n % 2 == 0は偶数判定に使われる"]], "vs": "continueは「その回だけスキップして次に進む」、breakは「二度と戻らずループを抜ける」で効果がまったく違う。この問題ではbreakがprintより前に書かれているため、i=5のときは何も出力されずに終わる点も見落としやすい。"}, "python-drill-q34": {"point": "デフォルト引数は呼び出し時に省略すると使われ、明示的に値を渡すとその値で上書きされる。", "why_asked": "「省略可能な引数」の扱いは関数設計の基本で、どちらの呼び出しでどの値が使われるかを正確に把握していないと予期しない挙動になりやすい。", "kid": "1回目はgreetingを省略しているのでデフォルトの\"Hi\"が使われ、2回目は\"Hello\"を明示的に渡しているのでそちらが使われる。", "eg": "注文時にトッピングを指定しなければ標準トッピング、指定すればそちらを使うお店の仕組みのようなもの。", "terms": [["デフォルト引数", "関数定義時にparam=値と書いておくと、呼び出し側で省略した場合にその値が使われる"], ["f-string", "f\"...\"の中に{変数}を書くと、その場で変数の値に置き換えて文字列を作る記法"]], "vs": "デフォルト引数の値がリストや辞書などミュータブル（可変）なオブジェクトだと、呼び出しをまたいで値が使い回されてしまう「可変デフォルト引数の罠」があるので別途注意が必要（この問題の\"Hi\"のような不変の文字列では起きない）。"}, "python-drill-q36": {"point": "Counter(...)は各要素の出現回数を数え、.most_common(n)は出現回数の多い順に上位n件を(値, 回数)のタプルのリストで返す。", "why_asked": "集計処理でCounterはよく使われるが、.most_common()の返り値の形（タプルのリスト）を勘違いすると後続処理でエラーになりやすい。", "kid": "\"a\"が3回、\"b\"が2回、\"c\"が1回登場するので、多い順に上位2件を取ると[(''a'', 3), (''b'', 2)]になる。", "eg": "選挙の開票速報で得票数トップ2の候補者名と得票数をあわせて発表するようなもの。", "terms": [["Counter", "collections標準ライブラリのクラス。イテラブルの各要素が何回出現したかを辞書のように数える"], [".most_common(n)", "出現回数が多い順に上位n件を(要素, 回数)のタプルのリストとして返すメソッド"]], "vs": "Counter(words)自体は辞書に近い性質を持つが、.most_common()を呼ぶと「値だけ」でも「辞書」でもなく「(値, 回数)のタプルのリスト」という別の形になる点が誤解されやすい。"}, "python-drill-q37": {"point": "defaultdict(list)は存在しないキーへ最初にアクセスした時点で自動的に空リストを作るため、KeyErrorを気にせず.append()できる。", "why_asked": "通常のdictで同じことをするとKeyErrorになるため、頭文字などでグループ分けする集計処理で頻出するdefaultdictの挙動を知らないと余計な初期化コードを書いてしまう。", "kid": "\"a\"で始まる単語（ant, ape）は自動的にキー''a''の下のリストにまとめられ、\"b\"で始まる単語（bee, bat）は''b''のリストにまとめられる。", "eg": "郵便物を宛先の頭文字ごとの棚に仕分けるとき、その頭文字の棚がまだ無ければ自動的に新しい棚を用意してくれる仕組みのようなもの。", "terms": [["defaultdict(list)", "collections標準ライブラリのクラス。存在しないキーにアクセスすると自動的に空リストを作って初期化する辞書"], [".append(x)", "リストの末尾にxを追加する破壊的メソッド"]], "vs": "通常のdictで同じコードを書くとgroups[word[0]]が存在しないキーの場合にKeyErrorで落ちる。defaultdictはその初期化処理（キーが無ければ空リストを用意する処理）を自動でやってくれる点が違い。"}, "python-drill-q38": {"point": "chain()は複数のイテラブルを1つに連結し、それぞれの「中身の要素」を順番に1つずつ取り出す。", "why_asked": "リスト・タプル・文字列など型の異なるイテラブルをまとめて走査したい場面で使われるが、「要素ごとに展開される」ことを知らないとリストのリストと勘違いしやすい。", "kid": "a, b, cそれぞれの中身が順番に展開され、文字列cは1文字ずつ''5'',''6''として並ぶ。結果は[1, 2, 3, 4, ''5'', ''6'']になる。", "eg": "別々のカゴに入った果物を1つの長い列に並べ替えるとき、カゴごとひとまとめにするのではなく果物を1個ずつ順番に取り出して並べるようなもの。", "terms": [["itertools.chain()", "複数のイテラブルを受け取り、それぞれの要素を順番につなげた1本のイテレータを作る"], ["イテラブル", "for文で1つずつ取り出せるオブジェクトの総称（リスト・タプル・文字列など）"]], "vs": "chain(a, b, c)は単純な連結とは違い、型の異なるイテラブルを混在させても要素単位で連結できる。文字列は「1文字ずつのイテラブル」として展開されるため、\"56\"はまとまった56にはならず''5''と''6''に分かれる点に注意。"}, "python-drill-q39": {"point": "elseブロックは例外が発生しなかったときだけ実行され、finallyブロックは例外の有無にかかわらず必ず最後に実行される。", "why_asked": "try文の4パーツ（try/except/else/finally）それぞれの実行条件を正確に理解していないと、リソース解放処理やログ出力を書く位置を間違えるため。", "kid": "n=2で0除算は起きないのでexceptは実行されず、正常終了時のみのelseで\"ok: 5.0\"が表示され、最後に必ずfinallyの\"done\"が表示される。", "eg": "手術で合併症が無ければ経過報告（else）をし、有っても無くても最後に必ず後片付け（finally）をするようなもの。", "terms": [["else（try文の）", "tryブロックで例外が発生しなかったときだけ実行されるブロック"], ["finally", "例外が発生してもしなくても、必ず最後に実行されるブロック"], ["except ZeroDivisionError", "ゼロで割ろうとしたときに発生する例外だけを捕まえる"]], "vs": "elseはtryの直後・exceptより後に実行される「例外が無かった場合専用」のブロックで、exceptとは排他（どちらか一方しか実行されない）。finallyはそれとは独立して常に実行される点が違う。"}, "python-drill-q40": {"point": "インスタンス変数はself.属性名で保持され、メソッド呼び出しをまたいで値が引き継がれる。", "why_asked": "「状態を持つオブジェクト」という考え方はクラス設計の基本であり、同じインスタンスに対する連続したメソッド呼び出しがどう値を積み上げていくかを把握しておく必要がある。", "kid": "Counter()でvalue=0のインスタンスができ、increment()を呼ぶたびにself.valueが1ずつ増えてその値を返すので、1回目は1、2回目は2になる。", "eg": "自動改札の通過カウンターのように、呼ぶたびに前回の値を覚えていて1ずつ増えていく仕組みのようなもの。", "terms": [["__init__", "インスタンス生成時に自動で呼ばれる初期化メソッド"], ["self", "インスタンス自身を指す。self.valueでそのインスタンス固有のデータにアクセスする"], ["インスタンス変数", "self.属性名で保持され、そのインスタンスが生きている間ずっと値を保持し続けるデータ"]], "vs": "print(c.increment(), c.increment())は左から右へ評価されるため、必ず1回目の呼び出し結果が1、2回目が2になる。関数のローカル変数と違い、self.valueは呼び出しが終わっても消えずに残り続ける点がインスタンス変数の特徴。"}, "python-drill-q41": {"point": "@decoratorは「元の関数を渡して新しい関数に置き換える」構文糖衣で、@shoutを付けたgreetを呼ぶと実際にはwrapperが実行される。", "why_asked": "デコレータはログ出力やキャッシュなど実務のライブラリで頻出するため、「関数を関数で包んで差し替える」仕組みを理解していないと挙動を追えなくなる。", "kid": "@shoutはgreet = shout(greet)と同じ意味。greet(\"yu\")を呼ぶと中身はwrapperが動き、元のgreetの結果\"hello, yu\"を大文字化して返す。", "eg": "手紙を書いた後に必ず大文字で清書し直してから送る担当者を1人挟むようなもの。", "terms": [["@デコレータ", "関数定義の直前に書き、その関数をデコレータ関数に渡して置き換える構文糖衣"], ["*args, **kwargs", "任意の個数の位置引数・キーワード引数をまとめて受け取る書き方"], [".upper()", "文字列をすべて大文字に変換するメソッド"]], "vs": "@shoutを付けたgreetは、見た目は元のgreet関数と同じ名前・同じ呼び出し方だが、中身は完全に別のwrapper関数に置き換わっている点が初見だと分かりにくい。"}, "python-drill-q42": {"point": "yieldを含む関数はジェネレータになり、next()を呼ぶたびに直前のyieldから再開して次の値まで実行が進む「使い切り」の性質を持つ。", "why_asked": "ジェネレータは一度消費した値を覚えておらず、途中までnext()した後にlist()やfor文で回すと「残り」しか取れないため、リストとの違いを知らないとデータの欠落に気づきにくい。", "kid": "next(gen)を2回呼んで3と2を先に取り出しているので、残っているのは1だけ。list(gen)は残りの1だけを含む[1]になる。", "eg": "引換券を1枚ずつ切り取って使うようなもので、一度切り取って使った券は後から全部見せてと言っても戻ってこない。", "terms": [["yield", "関数の実行を一時停止してその時点の値を返し、次にnext()が呼ばれたときにその続きから再開する"], ["ジェネレータ", "yieldを含む関数を呼び出すと得られる、1つずつ値を生成するイテレータ"], ["next()", "ジェネレータやイテレータから次の値を1つ取り出す組み込み関数"]], "vs": "リストは何度でも先頭から読み返せるが、ジェネレータは一度next()やforで進めた分は元に戻せない「使い切り」のイテレータである点が最大の違い。list(gen)は「残っている分だけ」をリスト化するのであって、最初からやり直すわけではない。"}, "python-drill-q43": {"point": "with文はブロックに入るときに__enter__を、抜けるとき（正常終了でも例外発生でも）に__exit__を必ず呼ぶ。", "why_asked": "ファイルやDB接続などリソースの後始末を確実に行うためのwith文の仕組みなので、__enter__/__exit__の呼ばれるタイミングを正確に知らないとリソースリークの原因を追えない。", "kid": "withブロックに入る瞬間に__enter__が呼ばれて\"open\"が出力され、ブロック内の\"using\"が実行された後、ブロックを抜ける瞬間に__exit__が呼ばれて\"close\"が出力される。", "eg": "会議室を使うときに入室記録をつけてから使い始め、使い終わったら必ず退室記録をつけるような、開始と終了が対になった仕組み。", "terms": [["with文", "__enter__と__exit__を持つオブジェクト（コンテキストマネージャ）を使って、開始処理と終了処理を自動的に対にする構文"], ["__enter__", "withブロックに入るときに自動で呼ばれるメソッド"], ["__exit__", "withブロックを抜けるときに自動で呼ばれるメソッド（例外の有無にかかわらず呼ばれる）"]], "vs": "try/finallyでも同様に「必ず後処理をする」ことはできるが、with文はそのパターンを再利用可能なクラスとして切り出せる点が違う。__exit__がFalseを返すとブロック内で発生した例外はそのまま外に伝播する（Trueを返すと例外が握りつぶされる）点も紛らわしい。"}, "python-drill-q44": {"point": "内側の関数は外側の関数のローカル変数を「覚えたまま」返される（クロージャ）ため、外側の関数を呼ぶたびに独立した状態を持つ関数が作られる。", "why_asked": "関数を返す関数（ファクトリ関数）はコールバックや設定値の異なる関数を量産する場面で使われるため、それぞれが独立した値を覚えている仕組みを理解しておく必要がある。", "kid": "doubleはfactor=2を、tripleはfactor=3をそれぞれ覚えたまま返された関数なので、同じ5を渡しても別々の答え（10と15）になる。", "eg": "同じレシピ（multiply）を使っても、2倍にする担当と3倍にする担当で別々の係数を持たせて独立して働かせるようなもの。", "terms": [["クロージャ", "外側の関数のローカル変数を覚えたまま返される内側の関数。外側の関数が終わった後もその変数を保持し続ける"], ["make_multiplier(factor)", "呼び出すたびに新しいfactorの値を持つ関数（multiply）を生成して返す、いわゆるファクトリ関数"]], "vs": "doubleとtripleは同じmultiplyという定義から作られているが、呼び出しごとに別々のfactorを覚えた別々の関数オブジェクトになる。グローバル変数を共有しているわけではなく、それぞれが独立した値を保持する点が誤解されやすい。"}, "python-drill-q45": {"point": "nonlocal宣言をすると、内側の関数から外側の関数のローカル変数を「読むだけでなく書き換え」られるようになる。", "why_asked": "クロージャで状態を保持するカウンタなどを作るときに必須の構文であり、nonlocalが無いと内側でのその変数への代入がエラーになる（Pythonのスコープ規則の落とし穴）ことを知っておく必要がある。", "kid": "nonlocal countのおかげでincrement()を呼ぶたびに外側のcountが1ずつ増え、その値が返される。呼ぶたびに前回の値が引き継がれるので1, 2, 3と増えていく。", "eg": "貯金箱の中身を毎回覚えていて、誰かがお金を入れるたびに前回の残高に上乗せしていくようなもの。", "terms": [["nonlocal", "内側の関数から、直接囲んでいる外側の関数（グローバルではない）のローカル変数を書き換え可能にする宣言"], ["make_counter()", "呼び出すたびに新しいcount=0を持つincrement関数を生成して返すファクトリ関数"]], "vs": "nonlocalが無い状態で内側の関数がcount += 1のように代入を試みると、Pythonはcountをその関数内だけの新しいローカル変数とみなしてしまい、代入前に参照しようとしてエラーになる。global宣言と役割は似ているが、globalはモジュールレベルの変数、nonlocalは外側の関数のローカル変数を対象にする点が違う。"}, "python-drill-q46": {"point": "@classmethodは第一引数にクラス自身(cls)を自動で受け取ってクラス変数にアクセスでき、@staticmethodはselfもclsも受け取らない普通の関数としてクラスの名前空間に置かれる。", "why_asked": "インスタンスを作らずにクラスから直接呼べるメソッドの使い分け（クラス変数を使うかどうか）は、ユーティリティ関数をクラスにまとめるときの設計判断に直結するため。", "kid": "describe()はcls.unitでクラス変数\"C\"を参照して\"unit is C\"を返す。to_fahrenheit(20)はselfもclsも使わず、渡された20だけで20*9/5+32=68.0を計算する。", "eg": "classmethodは会社の代表として会社の看板情報を答える係、staticmethodはたまたまその会社の道具箱を借りているだけの、外部から持ち込んだ計算専門の人のようなもの。", "terms": [["@classmethod", "第一引数に呼び出し元のクラス自身(cls)を自動で受け取るメソッド。クラス変数の参照・変更に使う"], ["@staticmethod", "selfもclsも受け取らない、クラスの名前空間に置かれただけの普通の関数"], ["クラス変数", "インスタンスではなくクラス自体に属する変数（unit = \"C\"のように定義）"]], "vs": "通常のインスタンスメソッド（第一引数self）はインスタンスを経由してインスタンス自身のデータを扱うのに対し、classmethodはインスタンスを作らずクラス変数を扱え、staticmethodはクラスにもインスタンスにも依存しない独立した処理を書くためのもの、という三者の役割の違いが混同されやすい。"}, "python-drill-q47": {"point": "raise X from eは新しい例外Xを送出しつつ、元の例外eをXの__cause__属性として保持する。", "why_asked": "例外を変換して再送出する（低レベルの例外を意味のある高レベルの例外に包み直す）のはライブラリ設計の定石で、デバッグ時に元の原因を追跡するためにfrom eが何をしているか知っておく必要がある。", "kid": "int(\"abc\")がValueErrorを起こし、それをexceptで捕まえてraise RuntimeError(...) from eで新しくRuntimeErrorを送出する。外側で捕まえたerrはRuntimeErrorで、その__cause__には元のValueErrorが入っている。", "eg": "事故報告書（RuntimeError）を書くときに、原因となった元の出来事（ValueError）を添付資料として一緒に保存しておくようなもの。", "terms": [["raise X from e", "新しい例外Xを送出しつつ、元になった例外eを原因として明示的に紐づける構文"], ["__cause__", "raise ... from eによって新しい例外に記録される、原因となった元の例外オブジェクト"], ["except ValueError as e", "発生したValueErrorを変数eに束縛して捕まえる"]], "vs": "fromを付けずに単にexcept節の中でraise RuntimeError(...)だけを書いた場合でも、Pythonは自動的に元の例外を__context__として記録するが、fromを明示すると__cause__に入り、意図的な変換であることが明確になる点が違う。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'python-drill')
  AND q.explanation_data IS NOT NULL;

-- 2) q01: correct_indexが実行結果と矛盾していたデータ不整合を修正
--    (append("d")→pop()で items は3要素に戻り removed="d" になるのが正しい。
--     旧データは4要素のままの選択肢を正解としていた)
UPDATE public.questions
SET correct_index = 1,
    correct_indices = '[1]'::jsonb,
    explanation_data = explanation_data || jsonb_build_object('opt', '[".pop()は要素を削除して返す破壊的メソッド。.append(''d'')で足した''d''も、続く.pop()で取り出されるとitemsからは無くなるので、''d''が残ったままにはならない。", "正解。.append()は末尾に追加、引数なしの.pop()は末尾を取り出して削除するので、''d''を足してすぐ''d''を抜いた形になる。", ".append()はリストの先頭ではなく末尾に追加する。先頭に足したいなら.insert(0, x)を使う。", "空リストで引数なし.pop()を呼ぶとエラーになるが、今回は要素があるので正常に動く。"]'::jsonb)
WHERE source_ref = 'python-drill-q01';

-- 3) q35: setの表示順がPythonのハッシュランダム化で実行のたびに変わり、
--    出力が非決定的だった問題を sorted() を挟む形に修正（コード・選択肢・解説を全面差し替え）
UPDATE public.questions
SET code = 'words = ["apple", "banana", "avocado", "kiwi"]
first_letters = {w[0] for w in words}
print(sorted(first_letters))',
    question_text = '出力される内容は？',
    options = '["[''a'', ''b'', ''k'']", "[''a'', ''a'', ''b'', ''k'']", "[''apple'', ''avocado'', ''banana'', ''kiwi'']", "エラーになる（波括弧の内包表記はdict専用）"]'::jsonb,
    correct_index = 0,
    correct_indices = '[0]'::jsonb,
    explanation_data = '{"asked": "出力される内容は？（集合内包表記とsorted()による決定的な表示）", "point": "波括弧{式 for ...}はsetを作り重複を自動でまとめる。setは表示順が不定なのでsorted()を通して並び順を固定する。", "why_asked": "集合内包表記{式 for ...}はリストと違って重複を自動的にまとめてくれるが、setをそのままprintすると実行のたびに表示順が変わってしまうため、sorted()で順序を固定する書き方も合わせて知っておく必要がある。", "kid": "{w[0] for w in words}は各単語の頭文字だけを集めたsetを作る。\"apple\"と\"avocado\"はどちらも頭文字が''a''なので、setの性質上1つにまとまる。そのままprintするとsetは表示順がバラつくので、sorted()でアルファベット順のリストに直してから出している。", "eg": "たとえるなら、参加者の出身都道府県を集めて「重複なしの一覧」を作るときに、集めた順のままだとバラバラで見づらいので、五十音順に並べ替えてから発表するようなもの。", "terms": [["集合内包表記 {式 for ...}", "重複しない集合(set)を作る書き方。同じ値は自動的に1つにまとめられる"], ["set", "重複を持たない、順序を保証しないデータ型"], ["sorted()", "リストやsetなどを受け取り、並び替えた新しいリストを返す関数。元のデータは変更しない"]], "think": "1行目でwordsは4つの文字列。2行目の集合内包表記は各単語の先頭1文字(w[0])を集めてsetにする。\"apple\"→''a''、\"banana\"→''b''、\"avocado\"→''a''、\"kiwi\"→''k''なので、重複する''a''は1つにまとまり、中身は{''a'',''b'',''k''}という3要素のsetになる。3行目でsorted()に通すと、setの中身がアルファベット順のリストになり、実行のたびに順序が変わることなく[''a'', ''b'', ''k'']が安定して出力される。", "vs": "sorted()を使わずにprint(first_letters)とだけ書くと、中身は同じでも表示される順序(例えば{''k'', ''a'', ''b''}のように)が実行のたびに変わることがある。これはPythonのset自体が要素の並び順を保証しないため。順序を固定して見せたいときはsorted()やlist()を挟む。", "opt": ["正解。集合内包表記で頭文字''a'',''b'',''a'',''k''からsetを作ると重複する''a''がまとまり{''a'',''b'',''k''}になる。sorted()でアルファベット順のリストとして安定した順序で出力される。", "波括弧{}で書いているのでsetになり重複は自動的にまとめられる。''a''が2つ残ることはない。", "w[0]は各単語の先頭1文字だけを取り出す操作であり、単語全体(\"apple\"など)がそのまま集まるわけではない。", "波括弧{}の内包表記は、key: value形式なら辞書、今回のような単一の式ならsetになる。エラーにはならない。"]}'::jsonb
WHERE source_ref = 'python-drill-q35';

COMMIT;
